import {BoxHelper, Box3, ObjectLoader} from 'three';
import {loadObjWithMaterial} from '../../utils/load-obj';
import path from 'path';
import convert from 'convert-units';

import React from 'react';

const mtl = require('./sofa.mtl');
const obj = require('./sofa.obj');
const img = require('./texture.jpg');

const defaultWidth = {length: 180, unit: 'cm'};
const defaultDepth = {length: 80, unit: 'cm'};
const defaultHeight = {length: 70, unit: 'cm'};

let cachedJSONSofa = null;

export default {
  name: 'canapé',
  prototype: 'items',

  info: {
    title: 'Canapé',
    tag: ['mobilier', 'salon'],
    description: 'Canapé confortable pour salon',
    image: require('./sofa.png')
  },

  properties: {
    width: {
      label: 'Largeur',
      type: 'length-measure',
      defaultValue: defaultWidth
    },
    depth: {
      label: 'Profondeur',
      type: 'length-measure',
      defaultValue: defaultDepth
    },
    height: {
      label: 'Hauteur',
      type: 'length-measure',
      defaultValue: defaultHeight
    },
    altitude: {
      label: 'altitude',
      type: 'length-measure',
      defaultValue: {
        length: 0,
        unit: 'cm'
      }
    }
  },

  render2D: function (element, layer, scene) {
    let width = element.properties.get('width').get('length');
    let depth = element.properties.get('depth').get('length');
    let angle = element.rotation + 90;
    let textRotation = Math.sin(angle * Math.PI / 180) < 0 ? 180 : 0;

    let style = {stroke: element.selected ? '#0096fd' : '#000', strokeWidth: '2px', fill: '#84e1ce'};
    let arrow_style = {stroke: element.selected ? '#0096fd' : null, strokeWidth: '2px', fill: '#84e1ce'};

    return (
      <g transform={`translate(${-width / 2},${-depth / 2})`}>
        <rect x="0" y="0" width={width} height={depth} style={style}/>
        <line x1={width / 2} x2={width / 2} y1={depth} y2={1.5 * depth}
              style={arrow_style}/>
        <line
          x1={.35 * width}
          x2={width / 2}
          y1={1.2 * depth}
          y2={1.5 * depth}
          style={arrow_style}
        />
        <line
          x1={width / 2}
          x2={.65 * width}
          y1={1.5 * depth}
          y2={1.2 * depth}
          style={arrow_style}
        />
        <text
          x="0"
          y="0"
          transform={`translate(${width / 2}, ${depth / 2}) scale(1,-1) rotate(${textRotation})`}
          style={{textAnchor: 'middle', fontSize: '11px'}}
        >
          {element.type}
        </text>
      </g>
    );
  },

  render3D: function (element, layer, scene) {
    let width = element.properties.get('width').get('length');
    let height = element.properties.get('height').get('length');
    let depth = element.properties.get('depth').get('length');
    let altitude = element.properties.get('altitude').get('length');

    let onLoadItem = (object) => {
      let newWidth = convert(width).from('cm').to(scene.unit);
      let newHeight = convert(height).from('cm').to(scene.unit);
      let newDepth = convert(depth).from('cm').to(scene.unit);

      // Scale the 3D model to match the specified dimensions
      object.scale.set(newWidth / defaultWidth.length,
                      newHeight / defaultHeight.length,
                      newDepth / defaultDepth.length);

      let box = new BoxHelper(object, 0x99c3fb);
      box.material.linewidth = 2;
      box.material.depthTest = false;
      box.renderOrder = 1000;
      box.visible = element.selected;
      object.add(box);

      // Normalize the origin of this item
      let boundingBox = new Box3().setFromObject(object);

      let center = [
        (boundingBox.max.x - boundingBox.min.x) / 2 + boundingBox.min.x,
        (boundingBox.max.y - boundingBox.min.y) / 2 + boundingBox.min.y,
        (boundingBox.max.z - boundingBox.min.z) / 2 + boundingBox.min.z];

      object.position.x -= center[0];
      object.position.y -= center[1] - (boundingBox.max.y - boundingBox.min.y) / 2;
      object.position.z -= center[2];

      // Apply altitude
      object.position.y += altitude;

      return object;
    };

    if (cachedJSONSofa) {
      let loader = new ObjectLoader();
      let object = loader.parse(cachedJSONSofa);
      return Promise.resolve(onLoadItem(object));
    }

    return loadObjWithMaterial(mtl, obj, path.dirname(img) + '/')
      .then(object => {
        cachedJSONSofa = object.toJSON();
        let loader = new ObjectLoader();
        return onLoadItem(loader.parse(cachedJSONSofa))
      });
  },

  updateRender3D: ( element, layer, scene, mesh, oldElement, differences, selfDestroy, selfBuild ) => {

    let noPerf = () => { selfDestroy(); return selfBuild(); };

    if( differences.indexOf('selected') !== -1 )
    {
      mesh.traverse(( child ) => {
        if ( child instanceof BoxHelper ) {
          child.visible = element.selected;
        }
      });

      return Promise.resolve(mesh);
    }

    if( differences.indexOf('rotation') !== -1 ) {
      mesh.rotation.y = element.rotation * Math.PI / 180;
      return Promise.resolve(mesh);
    }

    return noPerf();
  }
};
