const localStorage = window.hasOwnProperty('localStorage') ? window.localStorage : false;
import { loadProject } from '../actions/project-actions';

const TIMEOUT_DELAY = 500;

let timeout = null;
let isDataLoadedFromDB = false; // Flag to track if we loaded from database

// Function to check if we're in iframe and request plan from parent
const requestPlanFromParent = () => {
  return new Promise((resolve) => {
    if (window.parent && window.parent !== window) {
      const messageHandler = (event) => {
        if (event.data.type === 'LOAD_PLAN_RESPONSE') {
          window.removeEventListener('message', messageHandler);
          resolve({
            planData: event.data.planData || null,
            hasSpecificPlanId: event.data.hasSpecificPlanId || false
          });
        }
      };

      window.addEventListener('message', messageHandler);

      // Single request without retries - for shared plans, data comes via LOAD_PLAN
      console.log('🔄 Requesting plan from parent...');
      window.parent.postMessage({ type: 'REQUEST_SAVED_PLAN' }, '*');

      // Reduced timeout for faster fallback to localStorage
      setTimeout(() => {
        window.removeEventListener('message', messageHandler);
        console.log('⏰ Plan request timed out, falling back to localStorage');
        resolve({ planData: null, hasSpecificPlanId: false });
      }, 1500);
    } else {
      resolve({ planData: null, hasSpecificPlanId: false });
    }
  });
};

export default function autosave(autosaveKey, delay) {

  return (store, stateExtractor) => {

    delay = delay || TIMEOUT_DELAY;

    if (!autosaveKey) return;

    // Enhanced loading with priority: Database > localStorage > New project
    const loadPlanData = () => {
      // Helper function to load from localStorage
      const loadFromLocalStorage = () => {
        if (localStorage && localStorage.getItem(autosaveKey) !== null) {
          console.log('💾 Loading plan from localStorage');
          let data = localStorage.getItem(autosaveKey);
          let json = JSON.parse(data);
          store.dispatch(loadProject(json));
          return true;
        }
        return false;
      };

      // Check if we should wait for database response
      const shouldWaitForDatabase = window.parent && window.parent !== window;

      // Priority 1: Try to load from database via parent window (only if in iframe)
      if (shouldWaitForDatabase) {
        console.log('🔍 Requesting plan from parent window...');
        requestPlanFromParent()
          .then((response) => {
            const { planData, hasSpecificPlanId } = response;

            if (planData) {
              console.log('🎯 Loading plan from database');
              store.dispatch(loadProject(planData));
              isDataLoadedFromDB = true;
            } else {
              // No database data
              if (hasSpecificPlanId) {
                // If we were trying to load a specific plan but it failed, start with new project
                // Don't fall back to localStorage as that would load the wrong plan
                console.log('❌ Specific plan not found, starting with new project');
              } else {
                // No specific plan requested, try localStorage
                console.log('🔄 No database plan, checking localStorage...');
                if (!loadFromLocalStorage()) {
                  console.log('✨ Starting with new project');
                }
              }
            }
          })
          .catch((error) => {
            console.log('🔄 Database request failed, using localStorage fallback');
            if (!loadFromLocalStorage()) {
              console.log('✨ Starting with new project');
            }
          });
      } else {
        // Not in iframe, directly try localStorage
        console.log('📱 Not in iframe, loading from localStorage...');
        if (!loadFromLocalStorage()) {
          console.log('✨ Starting with new project');
        }
      }
    };

    // Execute the loading logic
    loadPlanData();

    // Listen for direct plan loading (e.g., from shared plans and templates)
    const handleDirectPlanLoad = (event) => {
      if (event.data.type === 'LOAD_PLAN') {
        console.log('📥 Loading plan directly from template/shared viewer');
        const planData = event.data.data;
        if (planData) {
          store.dispatch(loadProject(planData));
          console.log('✅ Plan loaded successfully');

          // Immediately save to localStorage so it persists on refresh
          if (localStorage) {
            localStorage.setItem(autosaveKey, JSON.stringify(planData));
            console.log('💾 Template data saved to localStorage for persistence');
          }

          // Set flag to indicate we loaded from external source
          isDataLoadedFromDB = true;
        }
      }
    };

    // Add listener for direct plan loading - this should happen immediately
    window.addEventListener('message', handleDirectPlanLoad);

    //update - Enhanced autosave supporting both localStorage and database
    store.subscribe(() => {
      if (timeout) clearTimeout(timeout);
      timeout = setTimeout(() => {
        let state = stateExtractor(store.getState());
        const sceneData = state.scene.toJS();

        // Always save to localStorage for fallback/guest mode
        if (localStorage) {
          localStorage.setItem(autosaveKey, JSON.stringify(sceneData));
        }

        // Additionally, for authenticated users, auto-sync to database
        if (window.parent && window.parent !== window) {
          // Request current plan ID from parent to determine if we have an existing plan
          window.parent.postMessage({ type: 'REQUEST_CURRENT_PLAN_ID' }, '*');

          // Listen for the response with plan ID
          const planIdHandler = (event) => {
            if (event.data.type === 'CURRENT_PLAN_ID_RESPONSE') {
              window.removeEventListener('message', planIdHandler);
              const planId = event.data.planId;

              if (planId && isDataLoadedFromDB) {
                // We have an existing plan, use auto-save for existing plans
                window.parent.postMessage({
                  type: 'AUTO_SAVE_EXISTING_PLAN',
                  data: { planData: sceneData }
                }, '*');
              } else if (!planId) {
                // New plan - could use general auto-save (optional)
                // window.parent.postMessage({
                //   type: 'AUTO_SAVE_PLAN',
                //   data: { planData: sceneData }
                // }, '*');
              }
            }
          };

          window.addEventListener('message', planIdHandler);

          // Clean up listener after 1 second
          setTimeout(() => {
            window.removeEventListener('message', planIdHandler);
          }, 1000);
        }
      }, delay);
    });
  };
}
