import { FontLoader, TextGeometry, MeshBasicMaterial, Mesh, BoxHelper } from 'three';
import React from 'react';
import { HELVETIKER } from './helvetiker_regular.typeface.js';

const fontLoader = new FontLoader();
const font = fontLoader.parse(HELVETIKER);

const defaultFontSize = 16;
const defaultColor = '#000000';

// Helper function to calculate polygon area using Shoelace formula
function calculatePolygonArea(vertices) {
  if (!vertices || vertices.length < 3) return 0;

  let area = 0;
  let n = vertices.length;

  for (let i = 0; i < n; i++) {
    let j = (i + 1) % n;
    let vi = vertices[i];
    let vj = vertices[j];
    if (vi && vj) {
      area += vi.x * vj.y;
      area -= vj.x * vi.y;
    }
  }

  return Math.abs(area / 2);
}

// Helper function to check if point is inside polygon
function pointInPolygon(x, y, vertices) {
  if (!vertices || vertices.length < 3) return false;

  let inside = false;
  for (let i = 0, j = vertices.length - 1; i < vertices.length; j = i++) {
    let vi = vertices[i];
    let vj = vertices[j];
    if (!vi || !vj) continue;

    let xi = vi.x, yi = vi.y;
    let xj = vj.x, yj = vj.y;

    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }

  return inside;
}

export default {
  name: 'texte',
  prototype: 'items',

  info: {
    tag: ['texte'],
    title: 'Texte 3D',
    description: 'Texte en trois dimensions',
    image: require('./img.png')
  },

  properties: {
    text: {
      label: 'Nom de la pièce',
      type: 'string',
      defaultValue: 'Pièce'
    },
    fontSize: {
      label: 'Taille du texte',
      type: 'number',
      defaultValue: defaultFontSize
    },
    color: {
      label: 'Couleur du texte',
      type: 'color',
      defaultValue: defaultColor
    },
    showBorder: {
      label: 'Afficher le cadre',
      type: 'checkbox',
      defaultValue: false
    },
    showArea: {
      label: 'Afficher la surface',
      type: 'checkbox',
      defaultValue: true
    },
    altitude: {
      label: 'altitude',
      type: 'length-measure',
      defaultValue: {
        length: 0,
        unit: 'cm'
      }
    }
  },

  render2D: function (element, layer, scene) {

    let color = element.properties.get('color') || defaultColor;
    let text = element.properties.get('text') || '';
    let fontSize = element.properties.get('fontSize') || defaultFontSize;
    let showBorder = element.properties.get('showBorder') || false;
    let showArea = element.properties.get('showArea') || false;
    let textHorizontalPadding = defaultFontSize;
    let width = ( ( text.length - ( text.length / 2 ) ) * fontSize ) + textHorizontalPadding;
    let height = 2 * fontSize;

    // Calculate area if showArea is enabled
    let areaText = '';
    if (showArea && layer && layer.areas) {
      try {
        // Find the SMALLEST area containing this text element (for nested rooms)
        let elementX = element.x;
        let elementY = element.y;
        let smallestArea = null;
        let smallestAreaSize = Infinity;

        layer.areas.forEach((area, areaID) => {
          // Get vertices for this area
          let vertexIDs = area.vertices ?
            (area.vertices.toArray ? area.vertices.toArray() :
             area.vertices.toJS ? area.vertices.toJS() :
             area.vertices) : [];

          if (vertexIDs.length >= 3) {
            // Get actual vertex coordinates
            let vertices = [];
            vertexIDs.forEach(vID => {
              let vertex = layer.vertices.get(vID);
              if (vertex) {
                let v = vertex.toJS ? vertex.toJS() : vertex;
                if (v && typeof v.x === 'number' && typeof v.y === 'number') {
                  vertices.push({x: v.x, y: v.y});
                }
              }
            });

            if (vertices.length >= 3) {
              // Check if text is inside this area
              if (pointInPolygon(elementX, elementY, vertices)) {
                // Calculate area in cm²
                let areaInCm2 = calculatePolygonArea(vertices);
                // Keep track of the smallest area that contains the point
                if (areaInCm2 < smallestAreaSize) {
                  smallestAreaSize = areaInCm2;
                  smallestArea = areaInCm2;
                }
              }
            }
          }
        });

        // Format the smallest area found
        if (smallestArea !== null) {
          let areaInM2 = (smallestArea / 10000);
          if (areaInM2 >= 0.01) { // Only show if area is at least 0.01 m²
            areaText = areaInM2.toFixed(2) + ' m²';
          }
        }
      } catch (error) {
        console.log('Could not calculate area:', error);
      }
    }

    return (
      <g>
        {showBorder && (
          <rect
            x={-width / 2}
            y={-height / 2}
            fill="#FFF"
            width={width}
            height={height}
            stroke="#000"
            strokeWidth="2"
          />
        )}
        <text
          x="0"
          y={showArea && areaText ? -fontSize * 0.3 : 0}
          fontFamily="Arial, sans-serif"
          alignmentBaseline="middle"
          textAnchor="middle"
          fontSize={fontSize}
          fontWeight="600"
          fill={color}
          transform={'scale(1,-1)'}
        >
          {text}
        </text>
        {showArea && areaText && (
          <text
            x="0"
            y={fontSize * 0.7}
            fontFamily="Arial, sans-serif"
            alignmentBaseline="middle"
            textAnchor="middle"
            fontSize={fontSize * 0.8}
            fill={color}
            transform={'scale(1,-1)'}
          >
            {areaText}
          </text>
        )}
      </g>
    )
  },

  render3D: function (element, layer, scene) {

    let text = element.properties.get('text') || '';
    let size = element.properties.get('fontSize') || defaultFontSize;
    let textHorizontalPadding = defaultFontSize;
    let width = ( ( text.length - ( text.length / 2 ) ) * size ) + textHorizontalPadding;
    let color = element.properties.get('color') || defaultColor;

    let mesh = new Mesh(
      new TextGeometry( text, { size, height: 1, font }),
      new MeshBasicMaterial({color})
    );

    if (element.selected) {
      let box = new BoxHelper(mesh, 0x99c3fb);
      box.material.linewidth = 2;
      box.material.depthTest = false;
      box.renderOrder = 1000;
      mesh.add(box);
    }

    mesh.position.y += element.properties.getIn(['altitude','length']);
    mesh.position.x -= ( width / 2 );

    return Promise.resolve( mesh );
  }
};
