import React from 'react';
import PropTypes from 'prop-types';
import { MdMenu, MdUndo, MdCheck } from 'react-icons/md';
import { FaPlus, FaSave, FaMousePointer } from 'react-icons/fa';
import * as SharedStyle from '../../shared-style';
import {
    MODE_IDLE,
    MODE_3D_VIEW,
    MODE_VIEWING_CATALOG,
    MODE_WAITING_DRAWING_LINE,
    MODE_DRAWING_LINE,
    MODE_DRAWING_HOLE,
    MODE_DRAWING_ITEM
} from '../../constants';

const toolbarStyle = {
    backgroundColor: SharedStyle.PRIMARY_COLOR.main,
    display: 'flex',
    flexFlow: 'row nowrap',
    justifyContent: 'space-around',
    alignItems: 'center',
    padding: '8px 0',
    paddingBottom: 'calc(8px + env(safe-area-inset-bottom, 0px))',
    borderTop: `1px solid ${SharedStyle.PRIMARY_COLOR.alt}`,
    position: 'fixed',
    bottom: 0,
    left: 0,
    right: 0,
    zIndex: 100
};

const buttonStyle = {
    backgroundColor: 'transparent',
    border: 'none',
    color: '#fff',
    cursor: 'pointer',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '6px 12px',
    minWidth: '48px',
    minHeight: '48px',
    borderRadius: '8px',
    transition: 'background-color 0.2s ease'
};

const activeButtonStyle = {
    ...buttonStyle,
    backgroundColor: 'rgba(255, 255, 255, 0.2)'
};

const doneButtonStyle = {
    ...buttonStyle,
    backgroundColor: 'rgba(76, 175, 80, 0.6)',
    border: '2px solid rgba(76, 175, 80, 0.9)'
};

const iconStyle = {
    fontSize: '22px',
    marginBottom: '2px'
};

const labelStyle = {
    fontSize: '10px',
    fontWeight: '500',
    textTransform: 'uppercase'
};

const Icon3D = ({ style }) => <span style={{ ...iconStyle, ...style, fontWeight: 'bold' }}>3D</span>;
const Icon2D = ({ style }) => <span style={{ ...iconStyle, ...style, fontWeight: 'bold' }}>2D</span>;

const DRAWING_MODES = [
    MODE_WAITING_DRAWING_LINE,
    MODE_DRAWING_LINE,
    MODE_DRAWING_HOLE,
    MODE_DRAWING_ITEM
];

export default function MobileToolbar({ state, width, height, onMenuClick }, context) {
    const { projectActions, viewer3DActions, translator } = context;
    const mode = state.get('mode');
    const isDrawing = DRAWING_MODES.includes(mode);

    // Check if any elements are selected for undo/delete
    const selectedLayer = state.getIn(['scene', 'selectedLayer']);
    const selected = state.getIn(['scene', 'layers', selectedLayer, 'selected']);

    // Prepare the save action
    const handleSave = () => {
        // Trigger save via postMessage to parent
        if (window.parent && window.parent !== window) {
            const sceneData = state.get('scene').toJS();
            window.parent.postMessage({ type: 'REQUEST_CURRENT_PLAN_ID' }, '*');

            const saveHandler = (event) => {
                if (event.data.type === 'CURRENT_PLAN_ID_RESPONSE') {
                    window.removeEventListener('message', saveHandler);
                    const planId = event.data.planId;
                    window.parent.postMessage({
                        type: 'SAVE_PLAN',
                        data: {
                            planId: planId,
                            isUpdate: !!planId,
                            planData: sceneData
                        }
                    }, '*');
                }
            };
            window.addEventListener('message', saveHandler);
            setTimeout(() => window.removeEventListener('message', saveHandler), 2000);
        }
    };

    // Stop drawing mode
    const handleDone = () => {
        projectActions.rollback();
        projectActions.setMode(MODE_IDLE);
    };

    return (
        <nav style={{ ...toolbarStyle, width, height }} className="mobile-toolbar">
            {/* Catalog Button */}
            <button
                style={[MODE_VIEWING_CATALOG].includes(mode) ? activeButtonStyle : buttonStyle}
                onClick={() => projectActions.openCatalog()}
                aria-label={translator.t('Open catalog')}
            >
                <FaPlus style={iconStyle} />
                <span style={labelStyle}>{translator.t('Ajouter')}</span>
            </button>

            {/* 2D/3D Toggle */}
            <button
                style={[MODE_3D_VIEW].includes(mode) ? activeButtonStyle : buttonStyle}
                onClick={() => {
                    if ([MODE_3D_VIEW].includes(mode)) {
                        projectActions.setMode(MODE_IDLE);
                    } else {
                        viewer3DActions.selectTool3DView();
                    }
                }}
                aria-label={[MODE_3D_VIEW].includes(mode) ? '2D View' : '3D View'}
            >
                {[MODE_3D_VIEW].includes(mode) ? <Icon2D style={iconStyle} /> : <Icon3D style={iconStyle} />}
                <span style={labelStyle}>{[MODE_3D_VIEW].includes(mode) ? '2D' : '3D'}</span>
            </button>

            {/* Select / Done button — context-aware */}
            {isDrawing ? (
                <button
                    style={doneButtonStyle}
                    onClick={handleDone}
                    aria-label={translator.t('Done')}
                >
                    <MdCheck style={iconStyle} />
                    <span style={labelStyle}>{translator.t('Valider')}</span>
                </button>
            ) : (
                <button
                    style={[MODE_IDLE].includes(mode) ? activeButtonStyle : buttonStyle}
                    onClick={() => projectActions.setMode(MODE_IDLE)}
                    aria-label={translator.t('Select')}
                >
                    <FaMousePointer style={iconStyle} />
                    <span style={labelStyle}>{translator.t('Sélect')}</span>
                </button>
            )}

            {/* Undo */}
            <button
                style={buttonStyle}
                onClick={() => projectActions.undo()}
                aria-label={translator.t('Undo')}
            >
                <MdUndo style={iconStyle} />
                <span style={labelStyle}>{translator.t('Annuler')}</span>
            </button>

            {/* Save */}
            <button
                style={buttonStyle}
                onClick={handleSave}
                aria-label={translator.t('Save')}
            >
                <FaSave style={iconStyle} />
                <span style={labelStyle}>{translator.t('Sauver')}</span>
            </button>

            {/* Menu/Drawer Toggle */}
            <button
                style={buttonStyle}
                onClick={onMenuClick}
                aria-label={translator.t('Menu')}
            >
                <MdMenu style={iconStyle} />
                <span style={labelStyle}>{translator.t('Menu')}</span>
            </button>
        </nav>
    );
}

MobileToolbar.propTypes = {
    state: PropTypes.object.isRequired,
    width: PropTypes.number.isRequired,
    height: PropTypes.number.isRequired,
    onMenuClick: PropTypes.func.isRequired
};

MobileToolbar.contextTypes = {
    projectActions: PropTypes.object.isRequired,
    viewer3DActions: PropTypes.object.isRequired,
    translator: PropTypes.object.isRequired
};
