import React from 'react';
import PropTypes from 'prop-types';
import {FaSave as IconSave} from 'react-icons/fa';
import ToolbarButton from './toolbar-button';
import { Project } from '../../class/export';

export default function ToolbarDbSaveButton({state}, {translator}) {

  let saveProjectToDatabase = e => {
    e.preventDefault();

    // Clean state by unselecting all elements
    const cleanState = Project.unselectAll(state).updatedState;
    const sceneData = cleanState.get('scene').toJS();

    // Check if we're in an iframe (parent window exists)
    if (window.parent && window.parent !== window) {
      // Ask parent window if we're editing an existing plan
      window.parent.postMessage({
        type: 'REQUEST_CURRENT_PLAN_ID'
      }, '*');

      // Listen for response
      let timeoutId;
      const messageHandler = (event) => {
        if (event.data.type === 'CURRENT_PLAN_ID_RESPONSE') {
          window.removeEventListener('message', messageHandler);
          clearTimeout(timeoutId); // Clear the timeout since we got a response

          const currentPlanId = event.data.planId;
          const isUpdate = !!currentPlanId;

          // Send save request with appropriate data
          window.parent.postMessage({
            type: 'SAVE_PLAN',
            data: {
              planId: currentPlanId,
              isUpdate: isUpdate,
              name: isUpdate ? undefined : `Plan ${new Date().toLocaleDateString('fr-FR')} ${new Date().toLocaleTimeString('fr-FR')}`,
              planData: sceneData
            }
          }, '*');
        }
      };

      window.addEventListener('message', messageHandler);

      // Timeout after 2 seconds - only runs if no response received
      timeoutId = setTimeout(() => {
        window.removeEventListener('message', messageHandler);
        // Fallback to create new plan
        window.parent.postMessage({
          type: 'SAVE_PLAN',
          data: {
            isUpdate: false,
            name: `Plan ${new Date().toLocaleDateString('fr-FR')} ${new Date().toLocaleTimeString('fr-FR')}`,
            planData: sceneData
          }
        }, '*');
      }, 2000);
    } else {
      // Fallback: show message that database save requires authentication
      alert('Pour sauvegarder en base de données, veuillez utiliser le planificateur depuis l\'application principale.');
    }
  };

  return (
    <ToolbarButton active={false} tooltip={translator.t('Enregistrer')} onClick={saveProjectToDatabase}>
      <IconSave />
    </ToolbarButton>
  );
}

ToolbarDbSaveButton.propTypes = {
  state: PropTypes.object.isRequired,
};

ToolbarDbSaveButton.contextTypes = {
  translator: PropTypes.object.isRequired,
};